function polygonDirectionInset(g){
 if(g.view!=='walk')return '';
 const {start,end}=g.marker.heading,dx=end[0]-start[0],dy=end[1]-start[1],length=Math.hypot(dx,dy),d=[dx/length,dy/length],q=[-d[1],d[0]],at=(along,across=0)=>[32+along*d[0]+across*q[0],32+along*d[1]+across*q[1]];
 return `<div class="ca-polygon-direction"><span>Next side direction (enlarged)</span><svg data-polygon-direction-inset viewBox="0 0 64 64" width="64" height="64" role="img" aria-labelledby="crossing-angles-polygon-direction-title" aria-describedby="crossing-angles-polygon-direction-description"><title id="crossing-angles-polygon-direction-title">Next side direction, enlarged</title><desc id="crossing-angles-polygon-direction-description">An enlarged copy of the marker’s heading. The arrow points along the next side.</desc><line data-polygon-direction-heading x1="${tn(at(-20)[0])}" y1="${tn(at(-20)[1])}" x2="${tn(at(20)[0])}" y2="${tn(at(20)[1])}"/><path data-polygon-direction-arrow d="M ${txy(at(8,8))} L ${txy(at(20))} L ${txy(at(8,-8))}"/></svg></div>`;
}
function polygonSteps(g){
 if(g.view==='corner')return '';
 const split=g.view==='split',value=split?g.draw:g.walk,max=split?g.n-3:g.n,action=split?'poly-draw':'poly-walk';
 return `<div class="ca-row ca-polygon-steps">${button(action,split?'Undo diagonal':'Previous stop',value-1,`data-crossing-angles-poly-step="previous"${value===0?' disabled':''}`)}${button(action,split?'Draw next diagonal':'Next stop',value+1,`data-crossing-angles-poly-step="next"${value===max?' disabled':''}`)}</div>${p(g.counter,'polygon-counter')}`;
}
function polygonControls(work,g){
 const free=g.mode==='free',select=(action,label,choices,current)=>`<label for="crossing-angles-${action}">${label}</label><select id="crossing-angles-${action}" data-crossing-angles-action="${action}">${choices.map(([v,t])=>`<option value="${v}"${v===current?' selected':''}>${t}</option>`).join('')}</select>`;
 return `<section class="ca-controls" aria-label="Polygon frames controls">${free?select('poly-sides','Number of sides',Array.from({length:10},(_,i)=>[i+3,i+3]),g.n)+p(polyCopy.sidesNote)+select('poly-kind','Frame kind',[['regular','Regular'],['stretched','Stretched']],g.kind)+(g.kind==='stretched'?p(polyCopy.stretched):'')+select('poly-size','Drawing size',[['small','Small'],['large','Large']],g.size):p(polyCopy.panelCaption)}${button('poly-corner','Choose another corner',(g.corner+1)%g.n)}${p(polyCopy.cornerNote)}${button('rotation','Turn the whole picture',(g.rotation+30)%360)}${p(`Picture orientation: ${g.rotation}°`)}${p(polyCopy.rotationNote)}${select('poly-prompt','Choose something to try',(free?polygonPrompts:polygonPanelPrompts).map((c,i)=>[i,c.title]),work.polyPrompt)}<h3>${esc(g.prompt.title)}</h3>${p(g.prompt.text)}</section>`;
}
function polygonPage(work,g){
 return `<div class="ca-workbench"><div>${polygonSteps(g)}${polygonDirectionInset(g)}${polygonStage(g)}<div class="ca-polygon-reading">${p(g.text)}${(g.equations||[]).map(e=>p(e,'equation')).join('')}${g.perTurn?p(g.perTurn,'equation'):''}${g.fractionNote?p(g.fractionNote):''}</div>${p(g.chosen,'polygon-chosen')}${g.current?p(g.current,'polygon-current'):''}${g.view==='walk'?p(polyCopy.walkLegend,'legend'):''}${p(g.source)}${p(g.definition)}${p(g.naming)}</div>${polygonControls(work,g)}</div>`;
}
function matchingStage(g){
 const q=g.geometry,line=(r,attributes='',cls='')=>`<line ${attributes} class="${cls}" x1="${tn(r.start[0])}" y1="${tn(r.start[1])}" x2="${tn(r.end[0])}" y2="${tn(r.end[1])}"/>`,pts=points=>points.map(v=>v.map(tn).join(',')).join(' ');
 const labels=q.labels||[];
 return `<figure class="ca-figure ca-matching-figure"><div class="ca-stage ca-matching-stage" data-crossing-angles-stage data-crossing-angles-matching-stage><svg viewBox="0 0 640 560" role="img" aria-labelledby="crossing-angles-matching-diagram-title" aria-describedby="crossing-angles-matching-diagram-description"><title id="crossing-angles-matching-diagram-title">${esc(g.view==='build'?'Building matching triangles':g.view==='letters'?'Reading corresponding triangle points':'Comparing triangle outlines')}</title><desc id="crossing-angles-matching-diagram-description">${esc([q.description,g.legend,g.view==='build'?'':`${g.reasonLabel} ${g.text}`].filter(Boolean).join(' '))}</desc>${q.rectangle?`<polygon data-matching-rectangle class="ca-matching-rectangle" points="${pts(q.rectangle)}"/>`:''}<g class="ca-matching-guides">${(q.circles||[]).map((c,i)=>`<circle data-matching-guide="circle-${i}" cx="${tn(c.center[0])}" cy="${tn(c.center[1])}" r="${tn(c.radius)}"/>`).join('')}${(q.rays||[]).map((r,i)=>line(r,`data-matching-guide="ray-${i}"`)).join('')}</g>${(q.segments||[]).map((r,i)=>line(r,`data-matching-guide="segment-${i}"`,`ca-matching-segment ca-matching-${r.role||'candidate'}`)).join('')}${q.diagonal?line(q.diagonal,'data-matching-diagonal','ca-matching-diagonal'):''}${['reference','candidate'].map(role=>q[role]?`<polygon data-matching-outline="${role}" class="ca-matching-outline ca-matching-${role}" points="${pts(q[role].points)}"/>`:'').join('')}${(q.rightMarks||[]).map(r=>`<polyline data-matching-right="${esc(r.role||'candidate')}" class="ca-matching-right ca-matching-${esc(r.role||'candidate')}" points="${pts(r.points)}"/>`).join('')}${(q.meetings||[]).map((m,i)=>`<circle data-matching-meeting="${i}" class="ca-matching-meeting${m.selected?' ca-matching-selected':''}" cx="${tn(m.point[0])}" cy="${tn(m.point[1])}" r="${m.selected?5:4}"/>`).join('')}<g class="ca-leaders">${labels.map((l,i)=>line({start:l.point,end:l.anchor},`data-ca-leader="${i}"`)).join('')}</g>${labels.filter(l=>l.selected).map(l=>`<circle class="ca-matching-pair-dot ca-matching-${esc(l.role||'candidate')}" cx="${tn(l.point[0])}" cy="${tn(l.point[1])}" r="9"/>`).join('')}</svg>${labels.map((l,i)=>`<span class="ca-label ca-point-label ca-matching-label ca-matching-${esc(l.role||'candidate')}${l.selected?' ca-matching-selected':''}" data-crossing-angles-label="${esc(l.name)}" data-ca-label="${i}" data-ca-x="${l.anchor[0]}" data-ca-y="${l.anchor[1]}" style="left:${l.anchor[0]/6.4}%;top:${l.anchor[1]/5.6}%">${esc(l.name)}${l.givenAngle!==undefined?` · ${esc(l.givenAngle)}°`: ''}</span>`).join('')}</div></figure>`;
}
function matchingAdjacent(g){
 if(g.view==='build')return `<div class="ca-row">${button('match-step','Previous construction stage',g.step-1,`data-crossing-angles-match-step="previous"${g.step===0?' disabled':''}`)}${button('match-step','Next construction stage',g.step+1,`data-crossing-angles-match-step="next"${g.step===2?' disabled':''}`)}</div>${p(g.counter,'matching-counter')}`;
 if(g.view==='letters')return `${button('match-pair','Next point pair',(g.pair+1)%3)}${p(g.counter,'matching-counter')}`;
 return `<div class="ca-row">${[['explore','Move and turn'],['given','Line up the given parts']].map(([v,t])=>button('match-fit',t,v,`aria-pressed="${g.fit===v}"`)).join('')}</div>${g.fit==='explore'?`<div class="ca-row">${button('match-rotation','Turn copy 30°',(g.rotation+30)%360)}${button('match-flip','Flip copy')}${button('match-home','Reset pose')}</div><div class="ca-row">${button('match-move','Previous slide',g.move-1,`data-crossing-angles-match-slide="previous"${g.move===0?' disabled':''}`)}${button('match-move','Next slide',g.move+1,`data-crossing-angles-match-slide="next"${g.move===4?' disabled':''}`)}</div>${p(g.counter,'matching-counter')}${p(`Copy turn: ${g.rotation}°`)}${p(`Copy reflection: ${g.flip?'reflected':'unreflected'}`)}`:''}`;
}
function matchingPage(work,m){
 const g=m.matching,w=work.matching;
 const select=(action,label,values,current)=>`<label for="crossing-angles-${action}">${esc(label)}</label><select id="crossing-angles-${action}" data-crossing-angles-action="${action}">${values.map(([v,t])=>`<option value="${esc(v)}"${v===current?' selected':''}>${esc(t)}</option>`).join('')}</select>`;
 const chrome=`<div class="ca-row">${[['parts','Parts cards'],['panel','My waiting panel']].map(([v,t])=>button('match-mode',t,v,`aria-pressed="${w.mode===v}"`)).join('')}</div><div class="ca-row">${[['build','Build'],['fit','Compare'],['letters','Letters']].map(([v,t])=>button('match-view',t,v,`aria-pressed="${w.view===v}"`)).join('')}</div>`;
 if(g.missing)return `<section class="ca-matching-page">${chrome}${w.view==='fit'?`<div class="ca-row">${[['explore','Move and turn'],['given','Line up the given parts']].map(([v,t])=>button('match-fit',t,v,`aria-pressed="${w.fit===v}"`)).join('')}</div>`:''}<div data-crossing-angles-matching-region>${p(matchCopy.nullContext)}</div></section>`;
 const prompts=g.mode==='panel'?matchingPanelPrompts:matchingPrompts;
 return `<section class="ca-matching-page">${chrome}<div data-crossing-angles-matching-region><div class="ca-workbench ca-matching-workbench"><div><div class="ca-matching-adjacent">${matchingAdjacent(g)}</div>${matchingStage(g)}${p(g.caption)}${p(g.legend,'legend')}${g.view==='build'?p(g.text):`${p(g.completedNotice)}${p(g.currentPair,'matching-current')}${p(`${g.reasonLabel?g.reasonLabel+' ':''}${g.text}`)}`}${g.poseNote?p(g.poseNote):''}${g.view==='letters'?`${p(g.definition)}${p(g.naming)}${p(g.notation)}`:''}</div><section class="ca-controls" aria-label="Matching triangles controls">${g.mode==='parts'?`${select('match-case','Choose parts card',Object.entries(matchingCases).map(([id,c])=>[id,c.title]),w.case)}${button('match-variant','Another build',(g.variant+1)%g.variantCount)}${p(g.variantLabel)}`:''}${p(g.source)}${g.givens?.length?`<h3>Given parts</h3><ul class="ca-matching-givens">${g.givens.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}${g.chosen?p(g.chosen):''}${select('match-prompt','Choose something to try',prompts.map((v,i)=>[i,v.title]),w.prompt)}<h3>${esc(g.prompt.title)}</h3>${p(g.prompt.text)}</section></div></div></section>`;
}
function measures(g){return `<div class="ca-measures">${g.sectors.map(s=>p(`${s.name}: ${s.measure}°`)).join('')}</div>${p('AOB + BOC = 180°','equation')}${p('All four angles: 360°')}`;}
function build(work,m){const b=m.build,g=m.geometry;return `<div class="ca-workbench"><div>${stage(g)}${p(copy.arcLegend,'legend')}${measures(g)}</div><section class="ca-controls" aria-label="Explore controls"><label for="crossing-angles-angle">Angle AOB</label><select id="crossing-angles-angle" data-crossing-angles-action="angle">${Array.from({length:11},(_,i)=>15+i*15).map(v=>`<option value="${v}"${v===b.angle?' selected':''}>${v}°</option>`).join('')}</select><div class="ca-row">${button('angle','−15°',b.angle-15,`data-crossing-angles-step="less"${b.canLess?'':' disabled'}`)}${button('angle','+15°',b.angle+15,`data-crossing-angles-step="more"${b.canMore?'':' disabled'}`)}</div>${button('rotation','Turn the whole picture',(b.rotation+30)%360)}${p(`Picture orientation: ${b.rotation}°`)}<div class="ca-row">${['opposite','adjacent'].map(v=>button('pair',v==='opposite'?'Opposite pair':'Adjacent pair',v,`aria-pressed="${b.pair===v}"`)).join('')}</div>${p(g.selectedNames.map(name=>`${name}: ${g.sectors.find(s=>s.name===name).measure}°`).join(' · '),'selected')}<label for="crossing-angles-prompt">Choose something to try</label><select id="crossing-angles-prompt" data-crossing-angles-action="prompt">${crossingPrompts.map((c,i)=>`<option value="${i}"${i===work.prompt?' selected':''}>${esc(c.title)}</option>`).join('')}</select><h3>${esc(m.prompt.title)}</h3>${p(m.prompt.text)}</section></div>`;}
function panel(frame){const rect=frame.rectangle,corners=rect.corners,sub=frame.subscript, index=sub==='₁'?1:2;return `<section class="ca-panel" data-crossing-angles-panel="${index}"><h4>${esc(frame.title)}</h4>${p(`${frame.width} × ${frame.height}`,'dimensions')}<div class="ca-rectangle"><svg viewBox="0 0 240 240" role="img" aria-label="${esc(`${frame.title}, rectangle ${frame.width} by ${frame.height}. Four outside corners are right angles; both diagonals join opposite corners.`)}"><g transform="translate(-200 -160)"><polygon points="${corners.map(c=>c.map(n).join(',')).join(' ')}"/>${[[0,2],[1,3]].map(([a,b])=>`<line x1="${corners[a][0]}" y1="${corners[a][1]}" x2="${corners[b][0]}" y2="${corners[b][1]}"/>`).join('')}${corners.map(c=>{const dx=c[0]<320?1:-1,dy=c[1]<280?1:-1,s=Math.min(8,rect.width/4,rect.height/4);return `<path d="M ${c[0]+dx*s} ${c[1]} v ${dy*s} h ${-dx*s}"/>`;}).join('')}${frame.square?'<path d="M 326 274 L 320 268 L 314 274"/>':''}</g></svg></div><div class="ca-dimension-captions"><span class="ca-dimension">Width: ${frame.width}</span><span class="ca-dimension">Height: ${frame.height}</span></div>${stage({...frame.inset,description:frame.description},{title:'Crossing enlarged: same angles',inset:index})}</section>`;}
function learn(work,m){const card=crossingCards[work.card];let visual='',reading='';
 if(work.card>=4){const g=m.two,step=card.steps?.[work.step];visual=twoStage(g)+p(twoCopy.workedCaption)+twoReading(g);reading=step?p(step.text)+step.equations.map(e=>p(e,'equation')).join('')+`<div class="ca-row">${button('step','Previous reason',work.step-1,`data-crossing-angles-reason="previous"${work.step===0?' disabled':''}`)}${button('step','Next reason',work.step+1,`data-crossing-angles-reason="next"${work.step===2?' disabled':''}`)}</div>`:p(card.text)+(card.equations||[]).map(e=>p(e,'equation')).join('');}
 else if(work.card===3){if(!m.context)return `<section class="ca-teaching"><label for="crossing-angles-card">Choose an explanation</label>${cardSelect(work)}<h3>${esc(card.title)}</h3>${p(copy.nullContext)}</section>`;
 visual=`${p('My waiting Copy Frame panel','waiting-label')}${p(m.context.caseTitle)}${p(copy.panelNote)}<div class="ca-panels">${m.context.frames.map(panel).join('')}</div>`;
 reading=p(card.text)+p(copy.panelWaitingNote)+p(copy.subscriptNote)+p(m.context.statement)+p(copy.arcLegend,'legend');
 }else{visual=m.diagrams.map(d=>stage(d.geometry,{title:d.title})).join('');if(work.card===1){const step=card.steps[work.step];reading=`${p(step.text)}${step.equations.map(e=>p(e,'equation')).join('')}<div class="ca-row">${button('step','Previous reason',work.step-1,`data-crossing-angles-reason="previous"${work.step===0?' disabled':''}`)}${button('step','Next reason',work.step+1,`data-crossing-angles-reason="next"${work.step===2?' disabled':''}`)}</div>`;}else reading=p(card.text);}
 return `<section class="ca-teaching"><label for="crossing-angles-card">Choose an explanation</label>${cardSelect(work)}<h3 id="crossing-angles-card-title">${esc(card.title)}</h3><div class="${work.card===3?'ca-panel-lesson':'ca-workbench'}"><div>${visual}</div><div class="ca-reading">${reading}${work.card<3?p(copy.arcLegend,'legend'):''}</div></div></section>`;
}
function cardSelect(work){return `<select id="crossing-angles-card" data-crossing-angles-action="card">${crossingCards.map((c,i)=>`<option value="${i}"${i===work.card?' selected':''}>${esc(c.title)}</option>`).join('')}</select>`;}
// Chase keeps real-size controls outside the uniformly projected geometric plot.
const chaseButton=(action,label,value,extra='')=>`<button type="button" data-crossing-angles-action="${action}"${value===undefined?'':` data-crossing-angles-value="${esc(value)}"`} ${extra}>${esc(label)}</button>`;
function chaseStage(g,example=false){
 const shape=g.geometry,id=example?'crossing-angles-chase-example':'crossing-angles-chase',line=(a,b,attrs='')=>`<line ${attrs} x1="${n(a[0])}" y1="${n(a[1])}" x2="${n(b[0])}" y2="${n(b[1])}"/>`;
 const labels=[...shape.points.map(t=>({name:t.name,position:t.position||[t.point[0]+18,t.point[1]-18],target:t.point,point:true})),...shape.givens.map(t=>({name:t.name,text:t.label,position:t.position,target:shape.sectors.find(s=>s.name===t.name)?.leader||t.position}))];
 return `<figure class="ca-figure ca-chase-figure"><div class="ca-chase-diagram" data-chase-diagram><div class="ca-stage ca-chase-stage" data-crossing-angles-stage data-crossing-angles-chase-stage><svg viewBox="0 0 640 560" role="img" aria-labelledby="${id}-title" aria-describedby="${id}-description"><title id="${id}-title">${esc(g.familyLabel)}</title><desc id="${id}-description">${esc(shape.description)}</desc><g class="ca-lines">${shape.segments.map((r,i)=>line(r.start,r.end,`data-chase-line="${i}"`)).join('')}</g>${shape.sectors.map(s=>`<path class="ca-chase-sector${s.selected?' ca-chase-sector-selected':''}" data-chase-sector="${esc(s.name)}" d="${esc(s.path)}"/>`).join('')}${shape.rightMarks.map((m,i)=>`<polyline class="ca-mark" data-chase-right="${i}" points="${m.points.map(xy).join(' ')}"/>`).join('')}${shape.parallelMarks.map((m,i)=>`<polyline class="ca-parallel-mark" data-chase-parallel="${i}" points="${m.points.map(xy).join(' ')}"/>`).join('')}<g class="ca-leaders">${labels.map((l,i)=>line(l.target,l.position,`data-ca-leader="${i}"`)).join('')}</g></svg>${labels.map((l,i)=>`<span class="ca-label ${l.point?'ca-point-label':'ca-chase-given'}" data-crossing-angles-label="${esc(l.name)}" data-ca-label="${i}" data-ca-x="${l.position[0]}" data-ca-y="${l.position[1]}" style="left:${l.position[0]/6.4}%;top:${l.position[1]/5.6}%">${esc(l.text||l.name)}</span>`).join('')}</div><div class="ca-chase-target-band" aria-label="${g.quantityMode?(example?'Example quantities':'Choose a quantity'):(example?'Example angles':'Choose a marked angle')}">${g.targets.map((t,i)=>{const scalar=t.unit==='number',lines=`<span>${esc(t.name)}</span><span>${t.value===null||t.value===undefined?'':`${esc(t.value)}${scalar?'':'°'}`}</span><span>${t.shown?'shown':''}</span>`,attrs=`data-crossing-angles-chase-target="${esc(t.name)}"${scalar?'':` data-chase-leader-x="${t.leader[0]}" data-chase-leader-y="${t.leader[1]}"`}`;return example?`<div class="ca-chase-target ca-chase-example-target" ${attrs}>${lines}</div>`:`<button type="button" class="ca-chase-target" data-crossing-angles-action="chase-target" data-crossing-angles-value="${i}" ${attrs} aria-pressed="${g.targetIndex===i}" aria-label="Choose ${scalar?'':'angle '}${esc(t.name)}${t.value===null||t.value===undefined?'':`, ${esc(t.value)}${scalar?'':' degrees'}`}${t.shown?', shown':''}">${lines}</button>`;}).join('')}</div><svg class="ca-chase-connectors" data-chase-connectors aria-hidden="true" focusable="false">${g.targets.filter(t=>t.unit!=='number').map(t=>`<line data-chase-connector="${esc(t.name)}"/>`).join('')}</svg></div></figure>`;
}
function chasePage(g){
 if(g.view==='example')return `<section class="ca-chase-page ca-chase-example" data-crossing-angles-chase-region><h2>A different worked sketch</h2>${p(chaseCopy.exampleNotice)}<div class="ca-chase-workbench"><div>${chaseStage(g,true)}${g.geometry.facts.map(t=>p(t)).join('')}</div><section class="ca-chase-working" aria-label="Worked sketch steps">${p(g.counter,'chase-counter')}${g.working.map(t=>p(t,'equation')).join('')}<div class="ca-row">${chaseButton('chase-example-step','Previous example step',g.exampleStep-1,`data-chase-example-nav="previous"${g.exampleStep===0?' disabled':''}`)}${chaseButton('chase-example-step','Next example step',g.exampleStep+1,`data-chase-example-nav="next"${g.exampleStep===g.targets.length?' disabled':''}`)}</div>${chaseButton('chase-return','Back to your sketch')}</section></div></section>`;
 const a=g.active;
 return `<section class="ca-chase-page" data-crossing-angles-chase-region><div class="ca-chase-sketch-picker"><div><label for="crossing-angles-chase-case">Choose a sketch</label><select id="crossing-angles-chase-case" data-crossing-angles-action="chase-case">${g.caseOptions.map(c=>`<option value="${c.value}"${c.value===g.caseIndex?' selected':''}>${esc(c.label)}</option>`).join('')}</select></div>${chaseButton('chase-case','Another sketch',(g.caseIndex+1)%g.caseOptions.length,'data-chase-another')}</div>${p(chaseCopy.retained,'chase-visit')}<div class="ca-chase-workbench"><div>${chaseStage(g)}<div class="ca-chase-facts">${g.geometry.facts.map(t=>p(t)).join('')}</div><div class="ca-row ca-chase-pose">${chaseButton('chase-rotation','Turn sketch 30°',(g.rotation+30)%360)}${chaseButton('chase-restart','Start this sketch again')}</div></div><section class="ca-chase-question" aria-label="${g.quantityMode?'Find a quantity':'Find an angle'}"><label for="crossing-angles-chase-target">${g.quantityMode?'Choose a quantity':'Choose an angle'}</label><select id="crossing-angles-chase-target" data-crossing-angles-action="chase-target">${g.targets.map((t,i)=>`<option value="${i}"${i===g.targetIndex?' selected':''}>${esc(t.name)}</option>`).join('')}</select><h2>${esc(g.question)}</h2>${p(g.counter,'chase-counter')}${g.targetIndex===0?p(a.firstGuidance):''}<label for="crossing-angles-chase-answer">${esc(a.inputLabel)}</label><div class="ca-chase-entry"><input id="crossing-angles-chase-answer" data-crossing-angles-chase-answer type="text" readonly inputmode="none" autocomplete="off" value="${esc(a.draft)}" aria-label="${esc(a.inputLabel)}">${a.unit==='number'?'':'<span aria-hidden="true">°</span>'}</div><div class="ca-chase-pad" aria-label="Number pad">${['1','2','3','4','5','6','7','8','9','0'].map(d=>chaseButton('chase-digit',d,d)).join('')}${chaseButton('chase-backspace','Backspace')}${chaseButton('chase-clear','Clear')}</div><div class="ca-chase-reasons" role="group" aria-label="Choose a relationship">${a.reasons.map(r=>chaseButton('chase-reason',r.label,r.id,`aria-pressed="${r.selected}"`)).join('')}</div>${chaseButton('chase-check','Check',undefined,'class="ca-chase-check"')}<div class="ca-chase-feedback" role="status" aria-live="polite" aria-atomic="true">${p(a.feedback)}</div><div class="ca-row">${chaseButton('chase-target',g.quantityMode?'Previous question':'Previous angle',g.targetIndex-1,`data-chase-target-nav="previous"${g.targetIndex===0?' disabled':''}`)}${chaseButton('chase-target',g.quantityMode?'Next question':'Next angle',g.targetIndex+1,`data-chase-target-nav="next"${g.targetIndex===g.targets.length-1?' disabled':''}`)}</div><div class="ca-chase-help">${chaseButton('chase-hint','Hint')}${chaseButton('chase-example','A different worked sketch')}${chaseButton('chase-solution','Show this solution')}${a.hint?p(a.hint,'chase-hint'):''}${a.solution?p(a.solution,'chase-solution'):''}${a.helpNote?p(a.helpNote,'chase-help-note'):''}</div></section></div>${g.caption?p(g.caption,'chase-caption'):''}${p(g.returnInvitation,'chase-return-invitation')}</section>`;
}
export function renderCrossingAngles(work,context=null){const m=crossingAnglesModel(work,context),chase=work.page==='chase',matching=work.page==='matching',two=work.page==='parallel'||work.page==='learn'&&work.card>=4,tri=work.page==='triangle',poly=tri&&work.triView==='polygons';return `<section class="crossing-angles-root" data-crossing-angles-root><header class="ca-header"><div><h1 id="crossing-angles-title" tabindex="-1">${esc(chase?chaseCopy.title:matching?matchCopy.title:copy.title)}</h1>${p(chase?chaseCopy.instruction:matching?matchCopy.instruction:poly?polyCopy.instruction:tri?triCopy.instruction:two?(work.page==='parallel'?twoCopy.instruction:twoCopy.header):copy.instruction)}</div>${button('back','Back to Copy Frame')}</header><nav class="ca-row" aria-label="Crossing Angles pages">${[['build','Explore'],['learn','See why'],['parallel','Two crossings'],['triangle','Triangle corners'],['matching','Match triangles'],['chase','Find angles']].map(([v,t])=>button('page',t,v,`aria-pressed="${work.page===v}"`)).join('')}</nav><button type="button" data-crossing-angles-hear data-speak="${esc(crossingAnglesNarration(work,context))}" data-speak-lang="en">Hear this page</button>${p(chase?chaseCopy.modelNote:matching?matchCopy.modelNote:poly?polyCopy.modelNote:tri?triCopy.modelNote:two?twoCopy.modelNote:copy.modelNote,'model-note')}${chase?chasePage(m.chase):matching?matchingPage(work,m):tri?trianglePage(work,m):work.page==='build'?build(work,m):work.page==='parallel'?twoPage(work,m):learn(work,m)}${chase||matching||two||tri?'':p(copy.straightTurn)}${p(copy.lifetime,'lifetime')}<details class="ca-adult"><summary>For grown-ups</summary>${chase?p(chaseCopy.adultNote):matching?p(matchCopy.adultNote):`${p(copy.adultNote)}${p(twoCopy.adultNote)}${p(triCopy.adultNote)}${p(polyCopy.adultNote)}`}</details></section>`;}
// Labels keep their real text size on phones. Resolve the concrete narrow-ray
// collisions using measured HTML boxes, then move their decorative leaders.
function arrange(stage){
 const w=stage.clientWidth,h=stage.clientHeight;if(!w||!h)return;
 const labels=[...stage.querySelectorAll('[data-ca-label]')].map(node=>({node,x:Number(node.dataset.caX)*w/640,y:Number(node.dataset.caY)*h/560,tx:Number(node.dataset.caX)*w/640,ty:Number(node.dataset.caY)*h/560,hw:node.offsetWidth/2+3,hh:node.offsetHeight/2+3}));
 for(let k=0;k<160;k++){let overlap=false;for(const a of labels){a.x=Math.max(a.hw,Math.min(w-a.hw,a.x));a.y=Math.max(a.hh,Math.min(h-a.hh,a.y));}for(let i=0;i<labels.length;i++)for(let j=i+1;j<labels.length;j++){const a=labels[i],b=labels[j],dx=a.x-b.x,dy=a.y-b.y,ox=a.hw+b.hw-Math.abs(dx),oy=a.hh+b.hh-Math.abs(dy);if(ox>0&&oy>0){overlap=true;if(ox<oy){const s=dx===0?(i%2?1:-1):Math.sign(dx);a.x+=s*(ox/2+.2);b.x-=s*(ox/2+.2);}else{const s=dy===0?(i%2?1:-1):Math.sign(dy);a.y+=s*(oy/2+.2);b.y-=s*(oy/2+.2);}}}if(!overlap)break;}
 for(const a of labels){a.node.style.left=`${a.x/w*100}%`;a.node.style.top=`${a.y/h*100}%`;const line=stage.querySelector(`[data-ca-leader="${a.node.dataset.caLabel}"]`);line?.setAttribute('x2',n(a.x/w*640));line?.setAttribute('y2',n(a.y/h*560));}
}
export function bindCrossingAngles(work,context,ctx){
 const root=document.querySelector('[data-crossing-angles-root]');if(!root)return;
 const live=node=>root.isConnected&&root.contains(node)&&document.querySelector('[data-crossing-angles-root]')===root&&ctx.live(node);
 const stop=()=>{ctx.stopSpeech();ctx.stopSound();};
 for(const node of root.querySelectorAll('button,input,select,summary')){const guard=e=>{if(node.disabled||!live(node)){e.preventDefault();e.stopImmediatePropagation();}};for(const type of ['click','input','change','keydown'])node.addEventListener(type,guard,{capture:true});}
 const hear=root.querySelector('[data-crossing-angles-hear]');hear.addEventListener('click',()=>{if(live(hear))hear.dataset.speak=crossingAnglesNarration(work,context);},{capture:true});
 bindChaseControls(root,work,context,ctx,live,stop);
 for(const node of root.querySelectorAll('[data-crossing-angles-action]:not([data-crossing-angles-action^="chase-"])'))node.addEventListener(node.tagName==='SELECT'?'change':'click',()=>{if(!live(node)||node.disabled)return;const action=node.dataset.crossingAnglesAction;if(action==='back'){stop();ctx.back();return;}const raw=node.tagName==='SELECT'?node.value:node.dataset.crossingAnglesValue,value=['angle','rotation','prompt','card','step','two-lean','two-move','two-prompt','tri-a','tri-b','tri-gather','tri-proof','tri-prompt','poly-sides','poly-corner','poly-draw','poly-walk','poly-prompt','match-step','match-variant','match-rotation','match-move','match-pair','match-prompt'].includes(action)?Number(raw):raw;stop();if(!ctx.change(action,...(['match-flip','match-home'].includes(action)?[]:[value]))){if(node.tagName==='SELECT'){const keys={'angle':'angle','rotation':'rotation','prompt':'prompt','card':'card','two-spacing':'twoSpacing','two-lean':'twoLean','two-prompt':'twoPrompt','tri-a':'triA','tri-b':'triB','tri-size':'triSize','tri-prompt':'triPrompt','poly-sides':'polySides','poly-kind':'polyKind','poly-size':'polySize','poly-prompt':'polyPrompt'};if(action.startsWith('match-')){const key=action.slice(6),source=work.matching[work.matching.mode];node.value=String(key in work.matching?work.matching[key]:source[key]);}else if(keys[action])node.value=String(work[keys[action]]);}return;}ctx.render();let selector=`[data-crossing-angles-action="${action}"]`;if(node.tagName==='SELECT')selector=`#${node.id}`;else if(action==='angle'){const direction=node.dataset.crossingAnglesStep;selector=`[data-crossing-angles-step="${value===15?'more':value===165?'less':direction}"]`;}else if(action==='step')selector=`[data-crossing-angles-reason="${value===0?'next':value===2?'previous':node.dataset.crossingAnglesReason}"]`;else if(action==='two-move')selector=`[data-crossing-angles-tracing="${value===0?'next':value===4?'previous':node.dataset.crossingAnglesTracing}"]`;else if(['tri-gather','tri-proof'].includes(action))selector=`[data-crossing-angles-tri-step="${value===0?'next':value===2?'previous':node.dataset.crossingAnglesTriStep}"]`;else if(['poly-draw','poly-walk'].includes(action)){const max=action==='poly-draw'?(work.triMode==='panel'?1:work.polySides-3):(work.triMode==='panel'?4:work.polySides);selector=`[data-crossing-angles-poly-step="${value===0?'next':value===max?'previous':node.dataset.crossingAnglesPolyStep}"]`;}else if(action==='match-step')selector=`[data-crossing-angles-match-step="${value===0?'next':value===2?'previous':node.dataset.crossingAnglesMatchStep}"]`;else if(action==='match-move')selector=`[data-crossing-angles-match-slide="${value===0?'next':value===4?'previous':node.dataset.crossingAnglesMatchSlide}"]`;else if(['pair','page','match-mode','match-view','match-fit','two-mode','two-pair','tri-mode','tri-view','poly-view'].includes(action))selector+=`[data-crossing-angles-value="${esc(value)}"]`;ctx.focus(selector);});
 for(const stage of root.querySelectorAll('[data-crossing-angles-stage]')){arrange(stage);if(stage.hasAttribute('data-crossing-angles-chase-stage'))chaseConnectors(stage.parentElement);const observer=new ResizeObserver(()=>{if(root.isConnected&&root.contains(stage)&&document.querySelector('[data-crossing-angles-root]')===root){arrange(stage);if(stage.hasAttribute('data-crossing-angles-chase-stage'))chaseConnectors(stage.parentElement);}else observer.disconnect();});observer.observe(stage);}
}
// The decorative overlay uses CSS pixels, so its endpoints match native controls
// at every width without moving a control or changing the geometric projection.
function chaseConnectors(diagram){
 const plot=diagram.querySelector('[data-crossing-angles-chase-stage]'),overlay=diagram.querySelector('[data-chase-connectors]');if(!plot||!overlay)return;
 const box=diagram.getBoundingClientRect(),art=plot.getBoundingClientRect();
 for(const target of diagram.querySelectorAll('[data-crossing-angles-chase-target][data-chase-leader-x][data-chase-leader-y]')){
  const line=overlay.querySelector(`[data-chase-connector="${target.dataset.crossingAnglesChaseTarget}"]`),end=target.getBoundingClientRect();if(!line)continue;
  line.setAttribute('x1',n(art.left-box.left+Number(target.dataset.chaseLeaderX)*art.width/640));
  line.setAttribute('y1',n(art.top-box.top+Number(target.dataset.chaseLeaderY)*art.height/560));
  line.setAttribute('x2',n(end.left-box.left+end.width/2));line.setAttribute('y2',n(end.top-box.top+end.height/2));
 }
}
function bindChaseControls(root,work,context,ctx,live,stop){
 if(work.page!=='chase')return;
 const model=crossingAnglesModel(work,context).chase;
 const zero=new Set(['chase-restart','chase-backspace','chase-clear','chase-check','chase-hint','chase-solution','chase-example','chase-return']);
 const numeric=new Set(['chase-case','chase-target','chase-rotation','chase-example-step']);
 const actual=action=>({'chase-case':model.caseIndex,'chase-target':model.targetIndex,'chase-rotation':model.rotation,'chase-example-step':model.exampleStep})[action];
 const dispatch=(node,action,raw,event)=>{
  if(!live(node)||node.disabled)return;
  let value=raw;
  if(numeric.has(action)){
   if(typeof raw!=='string'||!/^(0|[1-9][0-9]*)$/.test(raw)){if(node.tagName==='SELECT')node.value=String(actual(action));return;}
   value=Number(raw);
  }
  const restore=()=>{if(node.tagName==='SELECT')node.value=String(actual(action));};
  if(numeric.has(action)&&(!Number.isSafeInteger(value)||value<0||value>({'chase-case':model.caseOptions.length-1,'chase-target':model.targets.length-1,'chase-rotation':330,'chase-example-step':model.targets.length})[action]||action==='chase-rotation'&&value%30!==0)){restore();return;}
  if(zero.has(action)&&raw!==undefined)return;
  if(!zero.has(action)&&!numeric.has(action)&&!['chase-digit','chase-reason'].includes(action))return;
  if(action==='chase-digit'&&(typeof value!=='string'||!/^([0-9])$/.test(value)))return;
  if(action==='chase-reason'&&!model.active?.reasons.some(r=>r.id===value))return;
  if(model.view==='example'?!['chase-example-step','chase-return'].includes(action):['chase-example-step','chase-return'].includes(action))return;
  event?.preventDefault();stop();
  if(!ctx.change(action,...(zero.has(action)?[]:[value]))){if(node.tagName==='SELECT')node.value=String(actual(action));return;}
  ctx.render();
  let selector=`[data-crossing-angles-action="${action}"]`;
  if(node.id)selector=`#${node.id}`;
  else if(node.hasAttribute('data-chase-another'))selector='[data-chase-another]';
  else if(node.hasAttribute('data-crossing-angles-chase-target'))selector=`button[data-crossing-angles-chase-target="${node.dataset.crossingAnglesChaseTarget}"]`;
  else if(node.hasAttribute('data-chase-target-nav'))selector=`[data-chase-target-nav="${value===0?'next':value===model.targets.length-1?'previous':node.dataset.chaseTargetNav}"]`;
  else if(node.hasAttribute('data-chase-example-nav'))selector=`[data-chase-example-nav="${value===0?'next':value===model.targets.length?'previous':node.dataset.chaseExampleNav}"]`;
  else if(action==='chase-return')selector='#crossing-angles-chase-answer';
  else if(action==='chase-example')selector=`[data-chase-example-nav="${model.exampleStep===model.targets.length?'previous':'next'}"]`;
  else if(action==='chase-digit'||action==='chase-reason')selector+=`[data-crossing-angles-value="${esc(value)}"]`;
  ctx.focus(selector);
 };
 for(const node of root.querySelectorAll('[data-crossing-angles-action^="chase-"]'))node.addEventListener(node.tagName==='SELECT'?'change':'click',event=>dispatch(node,node.dataset.crossingAnglesAction,node.tagName==='SELECT'?node.value:node.dataset.crossingAnglesValue,event));
 const input=root.querySelector('[data-crossing-angles-chase-answer]');
 input?.addEventListener('keydown',event=>{
  if(!live(input)||event.ctrlKey||event.altKey||event.metaKey)return;
  const action=/^[0-9]$/.test(event.key)?'chase-digit':({'Backspace':'chase-backspace','Delete':'chase-clear','Enter':'chase-check'})[event.key];if(!action)return;
  dispatch(input,action,action==='chase-digit'?event.key:undefined,event);
 });
}
